import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"GetBasicConfig","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetBasicConfig","slug":"getbasicconfig"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetBasicConfig.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetBasicConfig.md"}'),i={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetBasicConfig.md"};function l(c,a,d,o,r,p){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="getbasicconfig" tabindex="-1">GetBasicConfig <a class="header-anchor" href="#getbasicconfig" aria-label="Permalink to &quot;GetBasicConfig&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于配置BasicBlock模板的参数，获取自定义BasicBlock模板。BasicBlock模板的介绍请参考<a href="./MatmulConfig.html#table6981133810309">表 模板特性</a>。</p><p>使用该接口时可以优先考虑使用模板常量化。相比BasicBlock模板仅实现baseM、baseN、baseK常量化，模板常量化可以在此基础上实现singleCoreM、singleCoreN、singleCoreK、baseM、baseN、baseK的常量化，模板常量化的具体使用方式请参考<a href="./GetMatmulApiTiling.html#section618mcpsimp">Matmul Tiling常量化</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ constexpr MatmulConfig GetBasicConfig(const uint32_t basicM, const uint32_t basicN, const uint32_t basicK, const bool intrinsicsLimit = false, const bool batchLoop = false, const BatchMode bmmMode = BatchMode::BATCH_LESS_THAN_L1)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p>本接口的所有参数用于设置<a href="./MatmulConfig.html#table1761013213153">MatmulConfig结构体</a>中的参数，其中互相对应的参数的功能作用相同。</p><p><strong>表 1</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>basicM</td><td>输入</td><td>用于设置参数basicM。 与TCubeTiling结构体中的baseM参数含义相同，Matmul计算时base块M轴长度，以元素为单位。</td></tr><tr><td>basicN</td><td>输入</td><td>用于设置参数basicN。 与TCubeTiling结构体中的baseN参数含义相同，Matmul计算时base块N轴长度，以元素为单位。</td></tr><tr><td>basicK</td><td>输入</td><td>用于设置参数basicK。 与TCubeTiling结构体中的baseK参数含义相同，Matmul计算时base块K轴长度，以元素为单位。</td></tr><tr><td>intrinsicsLimit</td><td>输入</td><td>用于设置参数intrinsicsCheck。 当左矩阵或右矩阵在单核上内轴（即尾轴）大于等于65535（元素个数）时，是否使能循环执行数据从Global Memory到L1 Buffer的搬入。例如，左矩阵A[M, K]，单核上的内轴数据singleCoreK大于65535，配置该参数为true后，API内部通过循环执行数据的搬入。参数取值如下： false：当左矩阵或右矩阵在单核上内轴大于等于65535时，不使能循环执行数据的搬入（默认值）。true：当左矩阵或右矩阵在单核上内轴大于等于65535时，使能循环执行数据的搬入。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr><tr><td>batchLoop</td><td>输入</td><td>用于设置参数isNBatch。 是否多Batch输入多Batch输出。仅对BatchMatmul有效，使能该参数后，仅支持Norm模板，且需调用IterateNBatch实现多Batch输入多Batch输出。参数取值如下： false：不使能多Batch（默认值）。true：使能多Batch。</td></tr><tr><td>bmmMode</td><td>输入</td><td>用于设置参数batchMode。该参数用于BatchMatmul场景。 BatchMatmul场景中Layout类型为NORMAL时，设置BatchMatmul输入A/B矩阵的多batch数据总和与L1 Buffer的大小关系。参数取值如下： BatchMode::BATCH_LESS_THAN_L1：多batch数据总和&lt;L1 Buffer Size；BatchMode::BATCH_LARGE_THAN_L1：多batch数据总和&gt;L1 Buffer Size；BatchMode::SINGLE_LARGE_THAN_L1：单batch数据总和&gt;L1 Buffer Size。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p><a href="./MatmulConfig.html#table1761013213153">MatmulConfig结构体</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>使用本接口时，基本块大小baseM、baseN需满足：singleCoreM能被baseM整除，singleCoreN能被baseN整除。</li><li>本接口的参数basicM、basicN、basicK应与<a href="./../Matmul-Tiling侧接口/Matmul-Tiling类/TCubeTiling结构体.html#p17899165811566">TCubeTiling结构体</a>的baseM、baseN、baseK设置保持一致。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 配置BasicBlock模板的参数，获取自定义BasicBlock模板</span></span>
<span class="line"><span>constexpr MatmulConfig MM_CFG = GetBasicConfig(</span></span>
<span class="line"><span>    /* basicM              */ 128,</span></span>
<span class="line"><span>    /* basicN              */ 256,</span></span>
<span class="line"><span>    /* basicK              */ 64,</span></span>
<span class="line"><span>    /* intrinsicsLimit     */ false,</span></span>
<span class="line"><span>    /* batchLoop           */ false,</span></span>
<span class="line"><span>    /* batchMode           */ BatchMode::BATCH_LESS_THAN_L1</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>// 常规Matmul计算，最后输出使用自定义BasicBlock模板的计算结果</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm.SetBias(gmBias);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>mm.IterateAll(gm_c);</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div>`,18)])])}const m=t(i,[["render",l]]);export{b as __pageData,m as default};
